#!/bin/bash
set -e
ulimit -n 65535 || true

# Env:
#   SSH_USERS_HASHED   "user:$6$..." records generated by deploy.sh
#   SSH_USERS          plaintext fallback for manually-run containers
#   OVPN_UPSTREAM_HOST VM IP/host running OpenVPN (optional; enables /saeka-ovpn)
#   OVPN_UPSTREAM_PORT default 1194 (server must be proto tcp)
#   OVPN_PROFILE_B64   client .ovpn, base64 (optional; enables /cert)
OVPN_UPSTREAM_HOST="${OVPN_UPSTREAM_HOST:-}"
OVPN_UPSTREAM_PORT="${OVPN_UPSTREAM_PORT:-1194}"
UDPGW_MAX_CLIENTS="${UDPGW_MAX_CLIENTS:-1000}"
UDPGW_MAX_CONNECTIONS="${UDPGW_MAX_CONNECTIONS:-500}"

# ---- SSH accounts (tunnel-only, /bin/false shell) ---------------------------
PASSWORDS_HASHED=0
if [ -n "${SSH_USERS_HASHED:-}" ]; then
    SSH_USERS="$SSH_USERS_HASHED"
    PASSWORDS_HASHED=1
elif [ -z "${SSH_USERS:-}" ]; then
    # No users supplied: create one random account and print it to the logs.
    RANDOM_USER="saeka-$(</dev/urandom tr -dc 'a-z0-9' | head -c6 || true)"
    RANDOM_PASS="$(</dev/urandom tr -dc 'A-Za-z0-9' | head -c16 || true)"
    SSH_USERS="${RANDOM_USER}:${RANDOM_PASS}"
    echo "[+] No SSH_USERS supplied - generated one-off account:"
    echo "    username: ${RANDOM_USER}"
    echo "    password: ${RANDOM_PASS}"
    echo "    (shown once - write it down now)"
fi
IFS=',' read -ra PAIRS <<< "$SSH_USERS"
CREATED=0
for pair in "${PAIRS[@]}"; do
    user="${pair%%:*}"
    pass="${pair#*:}"
    user="${user,,}"
    [ -z "$user" ] && continue
    if ! [[ "$user" =~ ^[a-z_][a-z0-9_-]{0,31}$ ]]; then
        echo "[!] Skipping invalid username '${user}'"; continue
    fi
    if [ -z "$pass" ] || [ "$pass" = "$pair" ]; then
        echo "[!] Skipping '${user}' - no password (format user:pass)"; continue
    fi
    if ! id -u "$user" >/dev/null 2>&1; then
        useradd -m -s /bin/false "$user" || { echo "[!] useradd failed for '$user' - skipping"; continue; }
    fi
    if [ "$PASSWORDS_HASHED" -eq 1 ]; then
        printf '%s:%s\n' "$user" "$pass" | chpasswd -e || { echo "[!] chpasswd failed for '$user' - skipping"; continue; }
    else
        printf '%s:%s\n' "$user" "$pass" | chpasswd || { echo "[!] chpasswd failed for '$user' - skipping"; continue; }
    fi
    CREATED=$((CREATED + 1))
    echo "[+] SSH account ready: $user"
done
if [ "$CREATED" -eq 0 ]; then
    # Never boot without a working login: fall back to one generated account.
    RANDOM_USER="saeka-$(</dev/urandom tr -dc 'a-z0-9' | head -c6 || true)"
    RANDOM_PASS="$(</dev/urandom tr -dc 'A-Za-z0-9' | head -c16 || true)"
    useradd -m -s /bin/false "$RANDOM_USER" && printf '%s:%s\n' "$RANDOM_USER" "$RANDOM_PASS" | chpasswd
    echo "[!] No valid SSH account in SSH_USERS - generated one-off account:"
    echo "    username: ${RANDOM_USER}"
    echo "    password: ${RANDOM_PASS}"
fi


# nginx starts LAST, once every local service accepts connections. Starting it
# first would let a request arrive while a bridge is still booting (502/503).
wait_port() {
    local port="$1" tries="${2:-60}" i
    for ((i = 0; i < tries; i++)); do
        (exec 3<>"/dev/tcp/127.0.0.1/${port}") 2>/dev/null && return 0
        sleep 0.25
    done
    echo "[!] port ${port} did not come up in time - starting nginx anyway (watchdog keeps retrying)"
    return 1
}

start_dropbear() {
    dropbear -F -E -R -w -K 60 -p 127.0.0.1:2200 -b /etc/dropbear/banner.txt &
    DROPBEAR_PID=$!
}
start_udpgw() {
    badvpn-udpgw --listen-addr 127.0.0.1:7300 \
        --max-clients "$UDPGW_MAX_CLIENTS" \
        --max-connections-for-client "$UDPGW_MAX_CONNECTIONS" \
        --loglevel warning &
    UDPGW_PID=$!
}
start_ssh_bridge() {
    python3 /opt/ws_bridge.py 2222 127.0.0.1 2200 ssh &
    SSH_BRIDGE_PID=$!
}
start_ovpn_bridge() {
    python3 /opt/ws_bridge.py 2223 "$OVPN_UPSTREAM_HOST" "$OVPN_UPSTREAM_PORT" ovpn &
    OVPN_BRIDGE_PID=$!
}
start_cert() {
    python3 /opt/cert_server.py &
    CERT_PID=$!
}

echo "[+] Starting Dropbear on 127.0.0.1:2200..."
start_dropbear
echo "[+] Starting BadVPN UDPGW on 127.0.0.1:7300..."
start_udpgw
echo "[+] /saeka-ssh -> Dropbear"
start_ssh_bridge

OVPN_BRIDGE_PID=""
if [ -n "$OVPN_UPSTREAM_HOST" ]; then
    echo "[+] /saeka-ovpn -> ${OVPN_UPSTREAM_HOST}:${OVPN_UPSTREAM_PORT}"
    start_ovpn_bridge
else
    echo "[!] OVPN_UPSTREAM_HOST not set - /saeka-ovpn disabled (SSH unaffected)."
fi
start_cert

echo "[+] Starting watchdog..."
(
  while true; do
    sleep 10
    kill -0 "$DROPBEAR_PID"    2>/dev/null || { echo "[watchdog] dropbear died";    start_dropbear; }
    kill -0 "$UDPGW_PID"       2>/dev/null || { echo "[watchdog] udpgw died";        start_udpgw; }
    kill -0 "$SSH_BRIDGE_PID"  2>/dev/null || { echo "[watchdog] ssh bridge died";   start_ssh_bridge; }
    kill -0 "$CERT_PID"        2>/dev/null || { echo "[watchdog] cert server died";  start_cert; }
    if [ -n "$OVPN_BRIDGE_PID" ]; then
        kill -0 "$OVPN_BRIDGE_PID" 2>/dev/null || { echo "[watchdog] ovpn bridge died"; start_ovpn_bridge; }
    fi
  done
) &

wait_port 2200 || true
wait_port 2222 || true
[ -z "$OVPN_UPSTREAM_HOST" ] || wait_port 2223 || true
echo "[+] Starting nginx..."
exec nginx -g "daemon off;"
